function claim(id,statement,sourceIds,category="evaluation",limitation=""){
  const certainty=["opioid-spastic-pattern","sentinel-before-reconstruction"].includes(id)?"low":"moderate";
  claims.push({...draft,id:cid(id),statement,sourceIds:sourceIds.map(src),evidenceCategory:category,certainty,limitation,applicablePopulation:"The identified adult synthetic teaching cases; constructed observations are not observed patient data.",lastCheckedOn:"2026-11-02"});
}
claim("mixed-discharge-parallel-evaluation","A plausible medication-associated prolactin rise warrants medication review and reassessment rather than automatic prioritization of pituitary imaging.",["pitarch"],"evaluation","One current open clinical review for this sequence; not a rule excluding pituitary disease. Existing independent metoclopramide and focal-discharge claims remain mapped.");
claim("implant-mri-not-discharge-assessment","A noncontrast silicone-implant-integrity MRI does not replace the conventional diagnostic pathway for spontaneous focal nipple discharge.",["acr-implant","pitarch"],"evaluation","Synthesis of two distinct protocol facts, not a direct comparative trial; age-appropriate mammography/targeted ultrasound and later contrast MRI remain individualized.");
claim("route-specific-midazolam-plan","Boosted-protease-inhibitor therapy requires individualized parenteral midazolam dosing and appropriate monitoring.",["nysdoh-hiv"],"management","Single adequate current guideline. Existing separate oral-contraindication/ART-continuity claims retained. Dose reduction is considered, especially with repeated dosing; no exact dose authored.");
claim("oxygenation-not-ventilation","Pulse oximetry does not establish adequate ventilation during procedural sedation.",["bsg-sedation"],"safety_boundary","One primary specialist guideline. The fictional capnography/chest observations are not a numerical toxicity threshold.");
claim("sedation-ventilation-response","Sedation-associated respiratory depression calls for assessment and support of ventilation, with reversal or additional anesthesia support as clinically needed.",["bsg-sedation"],"management","One primary specialist guideline. No reversal dose, saturation target, peak-effect time or universal rescue sequence authored.");
claim("primary-position-classification","Universal failed peristalsis with an abnormal relaxation pressure in an adequate primary-position series can establish an achalasia pattern despite a normal secondary-position pressure.",["chicago"],"evaluation","Primary classification consensus; technically adequate ten-swallow primary series supplied. It does not assert that manometry excludes every secondary cause.");
claim("opioid-spastic-pattern","Opioid exposure can accompany an achalasia-like spastic pattern, and assessment off opioids is advised when feasible.",["chicago"],"evaluation","Conditional, low-grade consensus guidance. Withdrawal must be coordinated; no abrupt cessation, fixed washout or universal reversibility is claimed.");
claim("secondary-achalasia-assessment","Older patients with achalasia-pattern physiology and substantial recent weight loss can require targeted assessment for a secondary junction lesion.",["acg-achalasia"],"evaluation","Single adequate directly retrieved primary guideline for the added alarm-based application. EUS/cross-sectional choice is individualized; no exact weight/time threshold or probability is invented.");
claim("sentinel-before-reconstruction","Sentinel-node mapping/biopsy is preferably coordinated with wide excision before flap or graft reconstruction can disrupt later mapping.",["cco-melanoma"],"management","Direct older primary technical guideline; current retained staging-indication evidence is independently mapped. No blanket contraindication after every excision or exact reliability effect is asserted.");
claim("colon-staging-coverage","Standard colon-cancer distant staging includes thoracic CT and adequate contrast-enhanced abdominal/pelvic assessment.",["ascrs-colon"],"evaluation","Single adequate retrieved guideline. Abdominal MRI can be a valid alternative; radiography, ultrasound and localization CT are not silently treated as equivalent complete pathways.");
claim("colon-pet-not-routine-substitute","Routine FDG PET-CT does not replace standard initial anatomic colon-cancer staging in the absence of a specific metastatic decision problem.",["ascrs-colon"],"evaluation","Primary guideline; not a claim PET never helps or that every PET-CT lacks diagnostic contrast CT. Each constructed prior report explicitly states its actual acquisition.");
claim("malignant-polyp-positive-margin","A positive or indeterminate invasive malignant-polyp margin generally warrants discussion of oncologic regional resection in a surgically suitable patient.",["ascrs-colon"],"management","One adequate primary guideline; no invented additional poor grade/LVI. A precise transverse-colon operation, individual preference and technical endoscopic alternatives require colorectal review.");
claim("sarcoma-method-and-tract","Planned sarcoma biopsy should avoid contaminating a separate unaffected compartment.",["essr2015","seom2024"],"management","The exact compartment rule is directly checked in older ESSR technique guidance; current SEOM corroborates tract removal/planning. Constructed rectus/adductor and triceps/biceps paths require clinician anatomy review.");
claim("sarcoma-initial-core-method","A feasible image-guided core biopsy is preferred initially for a suspicious deep extremity soft-tissue mass.",["seom2024","essr2015"],"evaluation","Open biopsy is a selected alternative, not universally wrong; no failed core, needle gauge, sample count or tumor subtype is invented.");
claim("rectus-anterior-compartment","Rectus femoris belongs to the anterior thigh compartment.",["thigh-anatomy"],"definition","Stable anatomy, independently synthesized from the review's compartment depiction. No figure adapted. The exact constructed tract still needs clinician review.");
claim("adductor-medial-compartment","Adductor longus is a muscle of the medial thigh compartment.",["adductor-anatomy"],"definition","Directly described anatomical membership; not a claim about all adductor variants or the clinical safety of a trajectory. B19's medial crossing is a constructed observation.");
claim("biceps-anterior-compartment","Biceps brachii is in the anterior arm compartment.",["arm-anatomy"],"definition","Single adequate imaging-anatomy review for stable membership. No source expression adapted; exact case route requires clinician review.");
claim("triceps-posterior-compartment","Triceps brachii is in the posterior arm compartment.",["arm-anatomy"],"definition","Single adequate imaging-anatomy review for stable membership. No source expression adapted; exact case route requires clinician review.");
claim("gastric-clone-not-diagnosis","Clonal B-cell expansion can occur in chronic inflammation and does not establish gastric MALT lymphoma without morphologic/clinical correlation.",["bsh-mzl"],"evaluation","Direct primary guideline caution. Preserved glands do not by themselves exclude every lymphoma; CD20 remains a lineage marker.");
claim("gastric-uncertainty-repeat-biopsy","Repeat endoscopy with biopsies is recommended when gastric MALT classification remains diagnostically uncertain.",["bsh-mzl"],"evaluation","One adequate primary guideline. Site documentation/comparative expert review is retained; no mandatory mapping grid, diagnostic probability or fixed interval is asserted.");
claim("specified-interval-decision-rule","Null-effect testing and comparison of a confidence interval with a separately defined effect target answer different statistical questions.",["nist-p","nist-ci"],"definition","The endpoint, benefit direction and whole-interval confirmation/exclusion rule are explicitly fictional protocol inputs. No source is represented as prescribing a clinical benefit cutoff; interval exclusion is not impossibility.");
claim("pdsa-hypothesis-not-proof","A small PDSA test uses local observations to select and evaluate a specific next change rather than establish its causal effect in advance.",["ahrq-pdca","ahrq-metrics"],"definition","The task-time/record-agreement table and prefill candidate are constructed hypotheses. No empirical effectiveness claim, adoption cutoff or answer analytics is introduced.");
for(const c of claims)for(const id of c.sourceIds){const s=sources.find(s=>s.id===id);if(!s)throw Error(id);s.evidenceClaimIds.push(c.id);}
